INSERT INTO `{PREFIX}whatsapp_templates` (`trigger_key`,`title`,`message_en`,`message_gu`,`media_type`,`is_active`) VALUES ('signup_welcome','Welcome — new restaurant','🎉 *Welcome to {site_name}, {owner_name}!*\n\nYour digital menu for *{restaurant_name}* is ready and live ✅\n\n📖 *Your menu link*\n{menu_url}\n\n🔐 *Login to your panel*\n{login_url}\nMobile: {mobile}\nPassword: {password}\n\n📦 Plan: *{plan_name}* (valid till {expiry_date})\n\n*Do these 3 things first:*\n1️⃣ Add your logo & colours → Design & Branding\n2️⃣ Check prices & photos → Menu Management\n3️⃣ Download & print your QR standee → QR & Standee\n\nReply to this message anytime if you need help — we''re happy to set it up with you.','🎉 *{site_name} માં આપનું સ્વાગત છે, {owner_name}!*\n\n*{restaurant_name}* નું ડિજિટલ મેનુ તૈયાર અને લાઈવ છે ✅\n\n📖 *તમારી મેનુ લિંક*\n{menu_url}\n\n🔐 *પેનલમાં લોગિન*\n{login_url}\nમોબાઈલ: {mobile}\nપાસવર્ડ: {password}\n\n📦 પ્લાન: *{plan_name}* ({expiry_date} સુધી)\n\n*સૌથી પહેલાં આ 3 કામ કરો:*\n1️⃣ લોગો અને કલર ઉમેરો → Design & Branding\n2️⃣ ભાવ અને ફોટા ચેક કરો → Menu Management\n3️⃣ QR સ્ટેન્ડી ડાઉનલોડ કરીને પ્રિન્ટ કરો → QR & Standee\n\nકોઈ પણ મદદ જોઈએ તો આ મેસેજનો જવાબ આપો — અમે સાથે બેસીને સેટ કરી આપીશું.','text',1) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`message_en`=VALUES(`message_en`),`message_gu`=VALUES(`message_gu`),`media_type`=VALUES(`media_type`);
INSERT INTO `{PREFIX}whatsapp_templates` (`trigger_key`,`title`,`message_en`,`message_gu`,`media_type`,`is_active`) VALUES ('signup_qr','Welcome — QR code','📲 *Your menu QR code — {restaurant_name}*\n\nPrint it and place it on every table. Customers scan → see the menu → order.\nMenu: {menu_url}','📲 *તમારો મેનુ QR કોડ — {restaurant_name}*\n\nપ્રિન્ટ કરીને દરેક ટેબલ પર મૂકો. ગ્રાહક સ્કેન કરે → મેનુ જુએ → ઓર્ડર કરે.\nમેનુ: {menu_url}','image',1) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`message_en`=VALUES(`message_en`),`message_gu`=VALUES(`message_gu`),`media_type`=VALUES(`media_type`);
INSERT INTO `{PREFIX}whatsapp_templates` (`trigger_key`,`title`,`message_en`,`message_gu`,`media_type`,`is_active`) VALUES ('signup_standee','Welcome — print-ready standee','🖨️ *Print-ready table standee — {restaurant_name}*\n\nGet it printed at any print shop (A5 / A4) and keep it on the tables or the counter.','🖨️ *પ્રિન્ટ માટે તૈયાર ટેબલ સ્ટેન્ડી — {restaurant_name}*\n\nકોઈ પણ પ્રિન્ટિંગની દુકાને (A5 / A4) પ્રિન્ટ કરાવો અને ટેબલ કે કાઉન્ટર પર મૂકો.','document',1) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`message_en`=VALUES(`message_en`),`message_gu`=VALUES(`message_gu`),`media_type`=VALUES(`media_type`);
INSERT INTO `{PREFIX}whatsapp_templates` (`trigger_key`,`title`,`message_en`,`message_gu`,`media_type`,`is_active`) VALUES ('menu_published','Menu updated','✅ *Your menu is updated and live!*\n\n{restaurant_name} — customers now see the latest items and prices.\n📖 {menu_url}\n\nTip: share this link on your WhatsApp status and Google Business profile.','✅ *તમારું મેનુ અપડેટ થઈને લાઈવ છે!*\n\n{restaurant_name} — ગ્રાહકોને હવે નવી આઇટમ અને ભાવ દેખાશે.\n📖 {menu_url}\n\nટીપ: આ લિંક WhatsApp સ્ટેટસ અને Google Business પ્રોફાઇલ પર શેર કરો.','text',1) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`message_en`=VALUES(`message_en`),`message_gu`=VALUES(`message_gu`),`media_type`=VALUES(`media_type`);
INSERT INTO `{PREFIX}whatsapp_templates` (`trigger_key`,`title`,`message_en`,`message_gu`,`media_type`,`is_active`) VALUES ('new_order','New order (to owner)','🛎️ *New order #{order_no}*\n📍 Table: *{table_no}*\n\n{items}\n\n💰 Total: *{total}*\nOpen Orders to accept it 👉 {login_url}','🛎️ *નવો ઓર્ડર #{order_no}*\n📍 ટેબલ: *{table_no}*\n\n{items}\n\n💰 કુલ: *{total}*\nસ્વીકારવા માટે Orders ખોલો 👉 {login_url}','text',1) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`message_en`=VALUES(`message_en`),`message_gu`=VALUES(`message_gu`),`media_type`=VALUES(`media_type`);
INSERT INTO `{PREFIX}whatsapp_templates` (`trigger_key`,`title`,`message_en`,`message_gu`,`media_type`,`is_active`) VALUES ('order_ready','Order ready (to customer)','🍽️ *Your order is ready!*\n\nOrder #{order_no} at *{restaurant_name}* is ready to be served. Enjoy your meal! 😊','🍽️ *તમારો ઓર્ડર તૈયાર છે!*\n\n*{restaurant_name}* માં ઓર્ડર #{order_no} પીરસવા માટે તૈયાર છે. ભોજનનો આનંદ માણો! 😊','text',1) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`message_en`=VALUES(`message_en`),`message_gu`=VALUES(`message_gu`),`media_type`=VALUES(`media_type`);
INSERT INTO `{PREFIX}whatsapp_templates` (`trigger_key`,`title`,`message_en`,`message_gu`,`media_type`,`is_active`) VALUES ('order_completed','Thank you + bill (to customer)','🙏 *Thank you for visiting {restaurant_name}!*\n\n🧾 Order #{order_no} · Total *{total}*\nView / download your bill:\n{invoice_url}\n\n📖 See our menu & order again anytime:\n{menu_url}\n\nWe''d love to see you again soon! ⭐','🙏 *{restaurant_name} માં પધારવા બદલ આભાર!*\n\n🧾 ઓર્ડર #{order_no} · કુલ *{total}*\nતમારું બિલ જુઓ / ડાઉનલોડ કરો:\n{invoice_url}\n\n📖 અમારું મેનુ જુઓ અને ફરી ઓર્ડર કરો:\n{menu_url}\n\nફરી જલ્દી પધારજો! ⭐','text',1) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`message_en`=VALUES(`message_en`),`message_gu`=VALUES(`message_gu`),`media_type`=VALUES(`media_type`);
INSERT INTO `{PREFIX}whatsapp_templates` (`trigger_key`,`title`,`message_en`,`message_gu`,`media_type`,`is_active`) VALUES ('plan_expiring','Plan expiring soon (to owner)','⏰ *Your plan ends in {days} day(s)*\n\nHi {name}, the *{plan_name}* plan for *{restaurant_name}* is valid till *{expiry_date}*.\n\nRenew now so your menu, QR ordering and KOT keep running without a break:\n👉 {renew_url}\n\nPay online (UPI / card) — the plan activates instantly.','⏰ *તમારો પ્લાન {days} દિવસમાં પૂરો થાય છે*\n\nનમસ્તે {name}, *{restaurant_name}* નો *{plan_name}* પ્લાન *{expiry_date}* સુધી માન્ય છે.\n\nમેનુ, QR ઓર્ડરિંગ અને KOT વિના અટક્યે ચાલુ રહે તે માટે અત્યારે જ રિન્યુ કરો:\n👉 {renew_url}\n\nઓનલાઇન (UPI / કાર્ડ) પેમેન્ટ કરો — પ્લાન તરત ચાલુ થઈ જશે.','text',1) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`message_en`=VALUES(`message_en`),`message_gu`=VALUES(`message_gu`),`media_type`=VALUES(`media_type`);
INSERT INTO `{PREFIX}whatsapp_templates` (`trigger_key`,`title`,`message_en`,`message_gu`,`media_type`,`is_active`) VALUES ('plan_expired','Plan expired (to owner)','⚠️ *Your plan has expired*\n\nHi {name}, the plan for *{restaurant_name}* ended on *{expiry_date}*, so your menu and online ordering are paused.\n\nRenew in 1 minute and go live again instantly:\n👉 {renew_url}\n\nAll your menu items, photos and data are safe.','⚠️ *તમારો પ્લાન પૂરો થઈ ગયો છે*\n\nનમસ્તે {name}, *{restaurant_name}* નો પ્લાન *{expiry_date}* ના રોજ પૂરો થયો, એટલે મેનુ અને ઓનલાઇન ઓર્ડર હાલ બંધ છે.\n\n1 મિનિટમાં રિન્યુ કરો અને તરત ફરી લાઈવ થાઓ:\n👉 {renew_url}\n\nતમારી બધી આઇટમ, ફોટા અને ડેટા સુરક્ષિત છે.','text',1) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`message_en`=VALUES(`message_en`),`message_gu`=VALUES(`message_gu`),`media_type`=VALUES(`media_type`);
INSERT INTO `{PREFIX}whatsapp_templates` (`trigger_key`,`title`,`message_en`,`message_gu`,`media_type`,`is_active`) VALUES ('payment_received','Payment received (to owner)','✅ *Payment received — thank you!*\n\n🏪 {restaurant_name}\n📦 Plan: *{plan_name}*\n💰 Amount: *{total}*\n📅 Valid till: *{expiry_date}*\n\n🧾 Invoice: {invoice_url}\n(Also available in Plans & Billing.)','✅ *પેમેન્ટ મળી ગયું — આભાર!*\n\n🏪 {restaurant_name}\n📦 પ્લાન: *{plan_name}*\n💰 રકમ: *{total}*\n📅 માન્ય: *{expiry_date}* સુધી\n\n🧾 ઇન્વૉઇસ: {invoice_url}\n(Plans & Billing માં પણ મળશે.)','text',1) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`message_en`=VALUES(`message_en`),`message_gu`=VALUES(`message_gu`),`media_type`=VALUES(`media_type`);
INSERT INTO `{PREFIX}whatsapp_templates` (`trigger_key`,`title`,`message_en`,`message_gu`,`media_type`,`is_active`) VALUES ('otp','Login OTP','🔐 *{otp}* is your {site_name} login code.\n\nValid for 5 minutes. Do not share this code with anyone.','🔐 *{otp}* તમારો {site_name} લોગિન કોડ છે.\n\n5 મિનિટ માટે માન્ય. આ કોડ કોઈને પણ ન આપશો.','text',1) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`message_en`=VALUES(`message_en`),`message_gu`=VALUES(`message_gu`),`media_type`=VALUES(`media_type`);
INSERT INTO `{PREFIX}whatsapp_templates` (`trigger_key`,`title`,`message_en`,`message_gu`,`media_type`,`is_active`) VALUES ('ticket_reply','Support reply (to owner)','💬 *We have replied to your support request.*\n\nOpen your panel to read it: {login_url}\n(Help & Support section)','💬 *તમારી સપોર્ટ વિનંતીનો અમે જવાબ આપ્યો છે.*\n\nવાંચવા માટે પેનલ ખોલો: {login_url}\n(Help & Support વિભાગ)','text',1) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`message_en`=VALUES(`message_en`),`message_gu`=VALUES(`message_gu`),`media_type`=VALUES(`media_type`);
INSERT INTO `{PREFIX}whatsapp_templates` (`trigger_key`,`title`,`message_en`,`message_gu`,`media_type`,`is_active`) VALUES ('daily_summary','Daily sales summary (to owner)','📊 *Today at {restaurant_name}* ({date})\n\n🧾 Orders: *{orders}*\n💰 Sales: *{total}*\n⭐ Top item: *{items}*\n\nFull reports: {login_url}','📊 *આજે {restaurant_name} માં* ({date})\n\n🧾 ઓર્ડર: *{orders}*\n💰 વેચાણ: *{total}*\n⭐ સૌથી વધુ વેચાયેલ: *{items}*\n\nપૂરો રિપોર્ટ: {login_url}','text',1) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`message_en`=VALUES(`message_en`),`message_gu`=VALUES(`message_gu`),`media_type`=VALUES(`media_type`);
